  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── ENUMS ───────────────────────────────────────────\nenum CancelReason {\n  CUSTOMER_REQUEST\n  INVALID_LEAD\n  WORKSHOP_DECLINED\n  NO_REPAIR_POSSIBLE\n  OTHER\n}\n\nenum Role {\n  TOW_TRUCK_DRIVER // Fahrer\n  ADMIN // Admin vom XYZ Abschlepper Unternehmen\n  SUPER_ADMIN // DeinMotorschaden\n}\n\nenum UserStatus {\n  PENDING\n  ACTIVE\n  INACTIVE\n  REJECTED\n}\n\nenum LeadStatus {\n  NEW\n  DISTRIBUTED // customer declined workshop\n  QR_SCANNED\n  WORKSHOP_SELECTED\n  IN_REPAIR\n  REPAIR_DONE\n  VEHICLE_DELIVERED\n  COMPLETED\n  CANCELLED\n}\n\nenum CommissionStatus {\n  PENDING\n  APPROVED\n  PAID\n  REJECTED\n}\n\n// ─── MODELS ──────────────────────────────────────────\n\n// model für Company rechieren was noch dazu gehört\n// Rahmi oder Yakup müssen das noch mir erklären.\nmodel User {\n  id String @id @default(cuid())\n\n  // ─── Personal (Fahrer-Daten) ───\n  email     String  @unique\n  firstname String\n  lastname  String\n  phone     String?\n\n  // ─── Supabase & Tech ───\n  supabaseId   String     @unique\n  role         Role       @default(TOW_TRUCK_DRIVER)\n  status       UserStatus @default(PENDING)\n  qrCode       String?    @unique\n  salesforceId String?    @unique\n\n  // ─── Company (TODO: in eigenes Model auslagern) ───\n  // Wenn aufgeteilt: alle companyXyz-Felder in neues Company-Model,\n  // User bekommt companyId + Relation zu Company.\n  companyId               String?\n  companyName             String?\n  companyAddress          String?\n  companyCity             String?\n  companyPostcode         String?\n  companyPhone            String?\n  companyEmail            String?\n  companyContactFirstname String?\n  companyContactLastname  String?\n  companyWebsite          String?\n\n  // ─── Relations ───\n  leads          Lead[]\n  commissions    Commission[]\n  auditLogs      AuditLog[]\n  cancelledLeads Lead[]       @relation(\"CancelledLeads\")\n  company        Company?     @relation(fields: [companyId], references: [id])\n\n  // ─── Timestamps ───\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@map(\"users\")\n}\n\nmodel Company {\n  id   String @id @default(cuid())\n  name String\n\n  users User[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@map(\"companies\")\n}\n\n// bin mir immernoch nicht 100% sicher.\n// Werkstatt (welche alle in der liste für den Kunden angezeigt werden zum auswählen)\nmodel Workshop {\n  id       String  @id @default(cuid())\n  name     String\n  address  String\n  city     String\n  postcode String // weitere noch hinzufügen zb Ansprechpartner\n  phone    String?\n  email    String?\n\n  leads Lead[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@map(\"workshops\")\n}\n\nmodel Lead {\n  id                String        @id @default(cuid())\n  // Storno details\n  cancelReason      CancelReason?\n  invoiceId         String?\n  cancelledAt       DateTime?\n  cancelledByUserId String?\n  cancelledBy       User?         @relation(\"CancelledLeads\", fields: [cancelledByUserId], references: [id])\n\n  // Customer info\n  customerLastName  String\n  vehicleMake       String\n  vehicleModel      String\n  vehicleHsn        String?\n  vehicleTsn        String?\n  vehicleType       String?\n  vehicleEngine     String?\n  vehicleMotorCode  String?\n  vehicleMileage    String?\n  vehicleFuelType   String?\n  vehicleProblems   String[]\n  vehicleDiagnosis  String?\n  breakdownStreet   String\n  breakdownPostcode String\n  breakdownCity     String\n\n  internNotice String?\n\n  // Status & tracking\n  status           LeadStatus @default(NEW)\n  salesforceId     String?    @unique\n  salesforceStatus String?\n\n  // Relations\n  towTruckDriver   User   @relation(fields: [towTruckDriverId], references: [id])\n  towTruckDriverId String\n\n  workshop   Workshop? @relation(fields: [workshopId], references: [id])\n  workshopId String?\n\n  qrScan     QRScan? // denke sollte ohne ? sein, weil wir per webapp alle leads mit dem qrCode generieren / später bereden\n  commission Commission?\n  auditLogs  AuditLog[]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@map(\"leads\")\n}\n\nmodel QRScan {\n  id        String   @id @default(cuid())\n  scannedAt DateTime @default(now())\n  utmMedium String? // AccountID_Abschlepper: AccountId_TowTruckDriver\n  utmSource String? // ADAC_Abschlepper / ADAC_TowTruckDriver\n\n  lead   Lead   @relation(fields: [leadId], references: [id])\n  leadId String @unique\n\n  createdAt DateTime @default(now())\n\n  landingpageLink String //defeulat: angebot seite von dm link enum erstellen\n\n  @@map(\"qr_scans\")\n}\n\nmodel Commission {\n  id         String           @id @default(cuid())\n  amount     Decimal          @db.Decimal(10, 2) // maximal 10 zeichen lange zahl mit mas .2 stellen am ende\n  currency   String           @default(\"EUR\")\n  status     CommissionStatus @default(PENDING)\n  paymentRef String? // Stripe / SEPA / PayPal reference\n  paidAt     DateTime?\n\n  lead   Lead   @relation(fields: [leadId], references: [id])\n  leadId String @unique\n\n  towTruckDriver   User   @relation(fields: [towTruckDriverId], references: [id])\n  towTruckDriverId String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"commissions\")\n}\n\nmodel AuditLog {\n  id      String  @id @default(cuid())\n  action  String // e.g. \"STATUS_CHANGED\", \"ACCOUNT_APPROVED\"\n  details String? // free text or JSON string\n\n  user   User?   @relation(fields: [userId], references: [id])\n  userId String?\n\n  lead   Lead?   @relation(fields: [leadId], references: [id])\n  leadId String?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"audit_logs\")\n}\n",
